import java.util.*;

public class Main {
    static class Edge {
        int diff;
        int index;
        Edge(int diff, int index) {
            this.diff = diff;
            this.index = index;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] a = new int[n];
        int[] odd = new int[n];
        int balance = 0;
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            balance += (a[i] & 1) == 0 ? 1 : -1;
            odd[i] = balance;
        }

        List<Edge> edges = new ArrayList<>();
        for (int i = 0; i + 1 < n; i++) {
            edges.add(new Edge(Math.abs(a[i + 1] - a[i]), i));
        }

        Collections.sort(edges, (e1, e2) -> {
            int cmp = e1.diff - e2.diff;
            if (cmp != 0) return cmp;
            return e1.index - e2.index;
        });

        int ans = 0;
        for (Edge e : edges) {
            if (k >= e.diff && odd[e.index] == 0) {
                int nk = k - e.diff;
                if (nk >= 0) {
                    ans++;
                    k = nk;
                }
            }
        }
        System.out.println(ans);
    }
}
